<template><section class="module-page module-composed-page admin-file-page"><header class="file-heading"><div><h1>文件</h1><p>课程资源文件、发布状态和下发任务。</p></div><div><el-button type="primary" icon="el-icon-upload2" @click="openUpload">上传资源</el-button><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></div></header><el-tabs v-model="tab"><el-tab-pane label="文件目录" name="resources"><section class="file-toolbar"><el-input v-model="keyword" prefix-icon="el-icon-search" clearable placeholder="输入关键字搜索" /><el-select v-model="type" clearable placeholder="全部类型"><el-option v-for="item in types" :key="item" :label="typeLabel(item)" :value="item" /></el-select><span class="file-count">共 {{ filtered.length }} 个文件</span></section><div v-if="filtered.length" class="file-grid"><article v-for="file in filtered" :key="file.resourceId" class="file-card"><header><span class="file-icon" :class="tone(file.resourceType)"><i :class="icon(file.resourceType)" /></span><span class="file-size">{{ formatSize(file.contentLength) }}</span><el-tag size="mini" :type="file.enabled?'success':'info'">{{ file.enabled?'启用':'停用' }}</el-tag></header><h2 :title="file.name">{{ file.name }}</h2><p>{{ file.courseName }}</p><small>{{ typeLabel(file.resourceType) }} · {{ file.sha256 ? '已校验' : '待校验' }}</small><footer><el-button size="mini" @click="toggle(file)">{{ file.enabled?'停用':'启用' }}</el-button><el-button size="mini" type="primary" :disabled="!file.enabled" icon="el-icon-upload2" @click="deliverAll(file)">下发全部</el-button></footer></article></div><div v-else class="file-empty"><i class="el-icon-folder-opened" /><strong>暂无资源文件</strong><span>点击右上角上传资源后将在此显示。</span></div></el-tab-pane><el-tab-pane label="下发记录" name="deliveries"><div class="module-table-wrap"><el-table v-loading="deliveryLoading" :data="deliveries" empty-text="暂无下发记录"><el-table-column prop="resourceId" label="资源" min-width="180" /><el-table-column prop="userId" label="用户" width="80" /><el-table-column prop="environmentId" label="环境" min-width="180" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="deliveryType(s.row.state)">{{ deliveryText(s.row.state) }}</el-tag></template></el-table-column><el-table-column prop="failureMessage" label="失败原因" min-width="180" show-overflow-tooltip /></el-table></div></el-tab-pane></el-tabs><el-dialog title="上传资源" :visible.sync="uploadDialog" width="520px"><el-form label-width="90px"><el-form-item label="所属课程"><el-select v-model="upload.courseId" filterable style="width:100%"><el-option v-for="item in courses" :key="item.course.courseId" :label="item.course.name" :value="item.course.courseId" /></el-select></el-form-item><el-form-item label="资源类型"><el-select v-model="upload.resourceType" style="width:100%"><el-option v-for="item in ['EBOOK','VIDEO','PPT','ARCHIVE']" :key="item" :label="typeLabel(item)" :value="item" /></el-select></el-form-item><el-form-item label="资源文件"><el-upload action="#" :auto-upload="false" :show-file-list="false" :on-change="chooseFile"><el-button icon="el-icon-folder-opened">选择文件</el-button></el-upload><small>{{ upload.name || '尚未选择文件' }}</small></el-form-item><el-form-item label="资源名称"><el-input v-model.trim="upload.name" /></el-form-item></el-form><span slot="footer"><el-button @click="uploadDialog=false">取消</el-button><el-button type="primary" :loading="uploading" @click="submitUpload">上传</el-button></span></el-dialog></section></template>
<script>
import { listAdminCourses, listAdminCourseDeliveries, setCourseResourceEnabled, deliverCourseResourceToAll, uploadCourseResource, addCourseResource } from '@/api/Courses'
export default {data:()=>({tab:'resources',loading:false,deliveryLoading:false,uploading:false,uploadDialog:false,courses:[],rows:[],deliveries:[],keyword:'',type:'',upload:{courseId:'',resourceType:'EBOOK',name:'',file:null}}),computed:{types(){return [...new Set(this.rows.map(r=>r.resourceType))]},filtered(){return this.rows.filter(r=>(!this.keyword||r.name.toLowerCase().includes(this.keyword.toLowerCase())||r.courseName.toLowerCase().includes(this.keyword.toLowerCase()))&&(!this.type||r.resourceType===this.type))}},created(){this.load();this.loadDeliveries()},methods:{async load(){this.loading=true;try{const r=await listAdminCourses();this.courses=r.data||[];this.rows=this.courses.reduce((all,item)=>all.concat((item.resources||[]).map(resource=>Object.assign({},resource,{courseName:item.course.name}))),[])}finally{this.loading=false}},async loadDeliveries(){this.deliveryLoading=true;try{const r=await listAdminCourseDeliveries();this.deliveries=r.data||[]}finally{this.deliveryLoading=false}},typeLabel(t){return({EBOOK:'电子书',VIDEO:'视频',PPT:'PPT',ARCHIVE:'课程数据'})[t]||t},icon(t){return({EBOOK:'el-icon-document',VIDEO:'el-icon-video-play',PPT:'el-icon-data-board',ARCHIVE:'el-icon-folder'})[t]||'el-icon-document'},tone(t){return({EBOOK:'tone-coral',VIDEO:'tone-blue',PPT:'tone-purple',ARCHIVE:'tone-green'})[t]||'tone-blue'},formatSize(bytes){if(!bytes)return'--';const units=['B','KB','MB','GB'];let value=Number(bytes),i=0;while(value>=1024&&i<units.length-1){value/=1024;i++}return `${value>=10||i===0?Math.round(value):value.toFixed(1)} ${units[i]}`},openUpload(){this.upload={courseId:this.courses[0]&&this.courses[0].course.courseId||'',resourceType:'EBOOK',name:'',file:null};this.uploadDialog=true},chooseFile(file){this.upload.file=file.raw;this.upload.name=file.name},async submitUpload(){if(!this.upload.courseId||!this.upload.file||!this.upload.name)return this.$message.warning('请选择课程和资源文件');this.uploading=true;try{const result=await uploadCourseResource(this.upload.file);await addCourseResource(this.upload.courseId,Object.assign({},result.data||{},{resourceType:this.upload.resourceType,name:this.upload.name}));this.$message.success('资源上传完成');this.uploadDialog=false;await this.load()}finally{this.uploading=false}},async toggle(row){await setCourseResourceEnabled(row.resourceId,!row.enabled);await this.load()},async deliverAll(row){try{await this.$confirm(`将把“${row.name}”发送到全部用户环境，是否继续？`,'确认下发',{type:'warning'});await deliverCourseResourceToAll(row.resourceId);await this.loadDeliveries();this.tab='deliveries'}catch(e){}},deliveryText(s){return({PENDING:'排队中',DISPATCHED:'已提交',RUNNING:'执行中',SUCCEEDED:'已完成',FAILED:'失败'})[s]||'未知'},deliveryType(s){return s==='SUCCEEDED'?'success':s==='FAILED'?'danger':s?'warning':'info'}}}
</script>
<style scoped>.admin-file-page{width:100%}.file-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:18px}.file-heading h1{margin:0;font-size:28px}.file-heading p{margin:6px 0 0;color:var(--ui-muted);font-size:13px}.file-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:18px;padding:14px 16px;background:var(--ui-surface);border-radius:12px;box-shadow:var(--ui-shadow)}.file-toolbar .el-input{width:min(360px,100%)}.file-toolbar .el-select{width:160px}.file-count{margin-left:auto;color:var(--ui-muted);font-size:12px}.file-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.file-card{min-width:0;padding:14px;background:#fff;border:1px solid var(--ui-border);border-radius:11px;box-shadow:var(--ui-shadow)}.file-card>header{display:flex;align-items:center;gap:7px;margin-bottom:14px}.file-icon{display:grid;place-items:center;width:46px;height:46px;color:#fff;border-radius:50%;font-size:21px}.tone-coral{background:#ff7279}.tone-blue{background:#4eb8ee}.tone-purple{background:#d58bea}.tone-green{background:#38c9aa}.file-size{margin-left:auto;color:var(--ui-text);font-size:12px}.file-card h2{margin:0;overflow:hidden;font-size:13px;text-overflow:ellipsis;white-space:nowrap}.file-card p{margin:7px 0;overflow:hidden;color:var(--ui-muted);font-size:12px;text-overflow:ellipsis;white-space:nowrap}.file-card>small{display:block;color:var(--ui-muted);font-size:11px}.file-card footer{display:flex;gap:6px;margin-top:13px;padding-top:11px;border-top:1px solid #f0f1f5}.file-card footer .el-button{flex:1;padding:7px 5px}.file-empty{display:grid;place-items:center;gap:8px;min-height:300px;color:var(--ui-muted);background:#fff;border:1px solid var(--ui-border);border-radius:12px}.file-empty i{font-size:44px;color:var(--ui-primary)}.file-empty strong{color:var(--ui-text);font-size:18px}.file-empty span{font-size:13px}@media(max-width:1100px){.file-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:820px){.file-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.file-heading{display:block}.file-heading .el-button{margin-top:10px}.file-toolbar{align-items:stretch;flex-direction:column}.file-toolbar .el-input,.file-toolbar .el-select{width:100%}.file-count{margin-left:0}.file-grid{grid-template-columns:1fr}}
</style>
